using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace Dafeiyu.Tests {
 public static class ConversationOwnershipTests {
  static int checks;static void Check(bool ok,string text){if(!ok)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
  public static int Main(){try{Run().GetAwaiter().GetResult();Console.WriteLine("Conversation ownership tests: "+checks+" passed");return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
  static async Task Run(){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ownership-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var settings=new PetSettings{ReadReplies=false,SaveChatHistory=true};settings.Text.BaseUrl="http://127.0.0.1";settings.Text.Model="fixture";settings.SystemPrompt="PET_PERSONA_ONLY";settings.AgentSystemPrompt="SHARED_WORK_ONLY";
   var catalog=ProjectCatalogStore.MigrateLegacy(settings);Check(catalog.Projects.Count==0 && !catalog.Sections.Any(s=>s.Id=="chat"),"fresh catalog has no chat section or default project");
   var quick=ProjectCatalogStore.QuickProject(catalog,settings);var first=ProjectCatalogStore.CreateConversation(catalog,quick.Id,"E包快聊");first.Mode="quick";first.PetId="e-bao";
   using(var one=ConversationWorkspace.Create(quick,first,root,"marfu",()=>new Api(),()=>new Speech(),()=>null,()=>settings,()=>true)){await one.Session.SendTextAsync("PRIVATE_E",one.EffectiveSettings(),"E包");await one.Session.FlushHistoryAsync();Check(one.Session.PersonaId=="e-bao"&&!one.EffectiveSettings().AgentEnabled,"quick conversation uses its owner and always stays pure chat");}
   var workProject=ProjectCatalogStore.CreateProject(catalog,"project",root);var work=workProject.Conversations[0];work.Mode="work";
   using(var one=ConversationWorkspace.Create(workProject,work,root,"e-bao",()=>new Api(),()=>new Speech(),()=>null,()=>settings,()=>true)){await one.Session.SendTextAsync("WORK_SHARED",one.EffectiveSettings(),"E包");await one.Session.FlushHistoryAsync();}
   using(var other=ConversationWorkspace.Create(workProject,work,root,"marfu",()=>new Api(),()=>new Speech(),()=>null,()=>settings,()=>true)){Check(other.Session.History.Messages.Any(m=>m.Content=="WORK_SHARED") && other.Session.PersonaId=="work","work record and history remain shared after pet switch");}
   var api=new Api();using(var session=new ConversationSession(api,new Speech(),()=>null)){await session.SendTextAsync("work",settings,"E包");Check(api.Last[0].Content.Contains("SHARED_WORK_ONLY")&&!api.Last[0].Content.Contains("PET_PERSONA_ONLY"),"work uses the independent prompt");settings.AgentEnabled=false;await session.SendTextAsync("chat",settings,"E包");Check(api.Last[0].Content.Contains("PET_PERSONA_ONLY")&&!api.Last[0].Content.Contains("SHARED_WORK_ONLY"),"ordinary chat uses the pet prompt");}
   var store=new ProjectCatalogStore(Path.Combine(root,"catalog.json"));store.Save(catalog);var reloaded=store.Load();Check(reloaded.QuickConversations.Single().PetId=="e-bao"&&reloaded.QuickConversations.Single().Id==first.Id,"fixed quick records preserve ownership and stable IDs on disk");
   var legacy=new ProjectCatalog{OwnershipVersion=0};var oldProject=ProjectCatalogStore.CreateProject(legacy,"legacy",root);var mixed=oldProject.Conversations[0];mixed.Mode=null;var log=new ConversationLog();log.Commit("PRIVATE_TURN","private reply");log.Commit("WORK_TURN","work reply");log.StartProcessing(log.Messages.Last().Id,true);var oldHistory=new HistoryStore(Path.Combine(ConversationWorkspace.ResolveDataDirectory(root,mixed.Id),"history"));await oldHistory.SaveAsync("e-bao",log.Messages);await oldHistory.FlushAsync();
   var upgraded=ProjectCatalogStore.UpgradeOwnership(legacy,root,new[]{"e-bao","marfu"},"e-bao");var personal=upgraded.QuickConversations.Single();Check(personal.PetId=="e-bao"&&personal.Mode=="chat"&&personal.Id!=mixed.Id,"legacy mixed history splits into an owned private record and shared work record");
   Check(new HistoryStore(Path.Combine(ConversationWorkspace.ResolveDataDirectory(root,mixed.Id),"history")).Load("work").Any(m=>m.Content=="WORK_TURN")&&!new HistoryStore(Path.Combine(ConversationWorkspace.ResolveDataDirectory(root,mixed.Id),"history")).Load("work").Any(m=>m.Content=="PRIVATE_TURN"),"shared work migration excludes private turns");
   Check(new HistoryStore(Path.Combine(ConversationWorkspace.ResolveDataDirectory(root,personal.Id),"history")).Load("e-bao").Any(m=>m.Content=="PRIVATE_TURN")&&Directory.GetFiles(Path.Combine(root,"ownership-backups",mixed.Id),"*.history").Length==1,"private turns and original encrypted backup are both retained");
   Check(Object.ReferenceEquals(upgraded,ProjectCatalogStore.UpgradeOwnership(upgraded,root,new[]{"e-bao","marfu"},"marfu")),"ownership migration is idempotent after commit");
   string rootLegacy=Path.Combine(root,"root-import");var rootHistory=new HistoryStore(Path.Combine(rootLegacy,"history"));await rootHistory.SaveAsync("e-bao",log.Messages);await rootHistory.FlushAsync();var originalBytes=File.ReadAllBytes(Directory.GetFiles(rootHistory.DirectoryPath,"*.history").Single());
   var rootCatalog=ProjectCatalogStore.UpgradeOwnership(new ProjectCatalog{OwnershipVersion=1},rootLegacy,new[]{"e-bao"},"e-bao");
   Check(rootCatalog.LegacyRootImported&&rootCatalog.QuickConversations.Count==1&&rootCatalog.UnassignedConversations.Count==1,"standalone legacy history becomes visible as private and shared work records");
   var rootPersonal=rootCatalog.QuickConversations.Single();Check(new HistoryStore(Path.Combine(ConversationWorkspace.ResolveDataDirectory(rootLegacy,rootPersonal.Id),"history")).Load("e-bao").Any(m=>m.Content=="PRIVATE_TURN"),"standalone personal history retains its pet owner");
   Check(originalBytes.SequenceEqual(File.ReadAllBytes(Directory.GetFiles(rootHistory.DirectoryPath,"*.history").Single()))&&Object.ReferenceEquals(rootCatalog,ProjectCatalogStore.UpgradeOwnership(rootCatalog,rootLegacy,new[]{"e-bao"},"e-bao")),"standalone import preserves original encrypted bytes and does not duplicate on reopen");
   string corrupt=Path.Combine(root,"corrupt.json");File.WriteAllText(corrupt,"{invalid");var broken=new ProjectCatalogStore(corrupt);bool blocked=false;try{broken.Load();}catch{ }try{broken.Save(new ProjectCatalog());}catch(IOException){blocked=true;}Check(blocked&&File.ReadAllText(corrupt)=="{invalid","failed catalog reads cannot overwrite the original file with an empty catalog");
  }
  sealed class Api:IConversationApi{public IList<ChatMessage> Last;public Task<string> ChatAsync(ConnectionSettings c,IList<ChatMessage> m,CancellationToken t){Last=m;return Task.FromResult("reply");}public Task<string> TranscribeAsync(ConnectionSettings c,byte[] b,CancellationToken t){throw new NotSupportedException();}public Task<byte[]> SpeechAsync(ConnectionSettings c,string v,string s,CancellationToken t){throw new NotSupportedException();}public void Dispose(){}}
  sealed class Speech:IReplySpeech{public Task SpeakAsync(string s,PetSettings c,CancellationToken t){return Task.FromResult(0);}public void Stop(){}public void SetVolume(int v){}public void Dispose(){}}
 }
}
